from typing import Any, Optional

import pydantic

from ...schemas.rapi.base import BaseRapiResponseSchema


class Datum(pydantic.BaseModel):
    bot: bool
    sn: str
    types: str
    highlight: list[str]


class Person(pydantic.BaseModel):
    sn: str
    firstName: Optional[str] = None
    middleName: Optional[str] = None
    lastname: Optional[str] = None
    friendly: Optional[str] = None


class SearchResultsSchema(pydantic.BaseModel):
    chats: list[dict[str, Any]]
    data: list[Datum]
    persons: list[Person]


class SearchResponseSchema(BaseRapiResponseSchema):
    results: SearchResultsSchema


class MonthlyHistogramItem(pydantic.BaseModel):
    entryCount: int
    month: str


class ParentId(pydantic.BaseModel):
    chatId: str
    messageId: int
    type: str


class Chat(pydantic.BaseModel):
    sender: str


class Message(pydantic.BaseModel):
    msgId: int
    outgoing: Optional[bool]
    time: int
    reqid: Optional[str]
    text: str
    chat: Optional[Chat]


class Entry(pydantic.BaseModel):
    olderMsgId: Optional[int]
    newerMsgId: Optional[int]
    message: Message
    highlight: list[str]


class Dialog(pydantic.BaseModel):
    sn: str
    peerEntryCount: int
    cursorOne: str
    parentId: Optional[ParentId]
    entries: list[Entry]


class SearchThreadsFeedResultsSchema(pydantic.BaseModel):
    exhausted: Optional[bool]
    cursorAll: Optional[str]
    totalEntryCount: Optional[int]
    monthlyHistogram: list[MonthlyHistogramItem]
    dialogs: Optional[list[Dialog]]
    persons: list[Person]


class SearchThreadsFeedResponseSchema(BaseRapiResponseSchema):
    results: SearchThreadsFeedResultsSchema


class SearchChatThreadsResponseSchema(SearchThreadsFeedResponseSchema): ...


class SearchAllDialogsResponseSchema(SearchThreadsFeedResponseSchema): ...


class SearchOneDialogsResponseSchema(SearchThreadsFeedResponseSchema): ...
